1	# Serve the built SPA AND reverse-proxy the API + MCP to the backend, so the
2	# prebuilt UI image works same-origin without Azure Static Web App "linking"
3	# (the no-clone `docker compose -f docker-compose.ghcr.yml up` path — #472).
4	#
5	# This is a TEMPLATE: the nginx image's entrypoint runs envsubst over
6	# /etc/nginx/templates/*.template at startup, so ${DATAQ_API_UPSTREAM} is filled
7	# from the env (default http://api:8000, set in frontend/Dockerfile; overridable
8	# in compose). Only env vars that are actually set are substituted, so nginx's
9	# own $uri / $host / $scheme runtime vars are left untouched.
10	
11	# The client-facing scheme, forwarded upstream (#1138). NOT `$scheme`.
12	#
13	# This container never terminates TLS — it listens on plain HTTP :8080 and the
14	# edge in front of it (Azure Container Apps' Envoy ingress, or whatever proxy a
15	# BYO deployment puts there) does. So `$scheme` here is *deterministically*
16	# `http` on every request, including ones the browser made over HTTPS. Sending
17	# `X-Forwarded-Proto: $scheme` doesn't merely lose information — `proxy_set_header`
18	# REPLACES the edge's correct `https` with our wrong `http`, so the API sees a
19	# plaintext request and marks the OTP session cookie **without `Secure`** on a
20	# live HTTPS deployment (ADR 0032; the backend's `_cookie_secure()` infers from
21	# exactly this header).
22	#
23	# So: prefer what the edge told us, and fall back to `$scheme` only when there is
24	# no edge header at all — the direct-connection case (compose, `docker run -p
25	# 8080`), where `$scheme` genuinely IS the client-facing scheme.
26	#
27	# Trust boundary, stated plainly: this makes nginx trust an inbound header. That
28	# is sound *because a client cannot reach this hop directly* — ACA's ingress is
29	# the only route in, and Envoy sets `X-Forwarded-Proto` itself from the TLS
30	# state, overwriting whatever the client sent. If you deploy this image with NO
31	# TLS-terminating proxy in front and expose it straight to the internet, a client
32	# CAN dictate the value; the only thing it influences is cookie-`Secure`
33	# inference (it grants no authentication and no authorization), and the
34	# belt-and-braces answer is to set `AUTH_SESSION_COOKIE_SECURE=true` explicitly
35	# on the API — which stops consulting the header at all.
36	#
37	# `map` lives in the `http` context: this template renders into conf.d/, which
38	# nginx includes inside `http { }`, so a top-level directive here is valid.
39	#
40	# The origin-secret guard's static "<secret>:<secret>" key is 2×40+1 = 81 bytes
41	# with the terraform-generated 40-char secret — over the 64-byte default
42	# map_hash_bucket_size, which aborts nginx at startup (#1380). 128 covers any
43	# secret up to 63 chars. MUST precede the first `map` block: parsing a `map`
44	# freezes the hash sizes, and a later directive is rejected as "duplicate".
45	map_hash_bucket_size 128;
46	map $http_x_forwarded_proto $dataq_forwarded_proto {
47	    default $http_x_forwarded_proto;
48	    ""      $scheme;
49	}
50	
51	# ── Origin-secret guard (#1355) ───────────────────────────────────────────────
52	# When DATAQ_ORIGIN_SECRET is set, every request must carry the matching
53	# X-DataQ-Origin-Secret header or it is 403'd. The intended sender is a fronting
54	# CDN/edge that stamps the header on origin fetches (AWS: CloudFront's custom
55	# origin header, set in deploy/terraform/aws/cloudfront.tf) — closing the gap
56	# where a THIRD PARTY's distribution origin-points at this container's
57	# (discoverable) load-balancer DNS: their edge doesn't know the secret. Note
58	# CloudFront overwrites any viewer-sent header of the same name with its own
59	# configured value, so the secret cannot be probed through the legitimate
60	# distribution either.
61	#
62	# When the variable is EMPTY (compose, BYOL, Azure — where ACA ingress is the
63	# only route in), the guard is fully open, including for requests that happen
64	# to carry the header. That is what the two-level map encodes:
65	#   rendered key = "<secret>:<request header>"
66	#   - secret empty  → key starts with ":" → the `~^:` regex allows everything
67	#   - secret set    → only the exact "<secret>:<secret>" concatenation allows;
68	#     an nginx map's exact match beats its regexes, and the secret is generated
69	#     alphanumeric (terraform `special = false`), so it can never contain the
70	#     ":" delimiter or map metacharacters.
71	map "${DATAQ_ORIGIN_SECRET}:$http_x_dataq_origin_secret" $dataq_origin_bad {
72	    default 1;
73	    "~^:"   0;
74	    "${DATAQ_ORIGIN_SECRET}:${DATAQ_ORIGIN_SECRET}" 0;
75	}
76	
77	# Second level: exempt the load balancer's OWN health check, which reaches the
78	# container directly (not through the CDN) and so can never carry the header.
79	# /_alb-health is served locally below and probes nothing but nginx itself —
80	# the frontend target's health must mean "nginx + bundle up", not "the api is
81	# up" (#1349). Exact map keys beat the regex, so the exemption wins.
82	map "$dataq_origin_bad:$uri" $dataq_origin_reject {
83	    default 0;
84	    "~^1:"  1;
85	    "1:/_alb-health" 0;
86	}
87	
88	server {
89	    listen 8080;
90	    server_name _;
91	    root /usr/share/nginx/html;
92	    index index.html;
93	
94	    # Origin-secret guard (#1355, maps above). Server-level so no location can
95	    # be forgotten; a bare `return` in an `if` at server context is one of the
96	    # two forms nginx's own docs bless ("if is evil" applies to content
97	    # handlers, not to return/rewrite).
98	    if ($dataq_origin_reject) {
99	        return 403;
100	    }
101	
102	    # Local health endpoint for the load balancer's target-group check (exempt
103	    # from the guard above — the LB probes the container directly, without the
104	    # CDN's header). Deliberately serves from nginx itself: frontend health
105	    # means "nginx + bundle up", never "the api is up" (#1349).
106	    location = /_alb-health {
107	        default_type text/plain;
108	        return 200 'ok';
109	    }
110	
111	    # Runtime app config (ADR 0028). Rendered from DATAQ_AUTH_* env by the same
112	    # startup envsubst, served BEFORE the app bundle so the SPA reads it
113	    # synchronously (window.__DATAQ_CONFIG__). One generic image, nothing baked.
114	    # This exact-match location wins over the static /config.js stub in the bundle.
115	    # Empty values → the SPA treats auth as unconfigured (fail-closed); dev-bypass
116	    # requires an explicit DATAQ_AUTH_MODE=bypass. no-cache so a restart with new
117	    # env takes effect. (Auth values are URLs/ids/scopes — no single-quote/$ to
118	    # break the returned string.)
119	    location = /config.js {
120	        default_type application/javascript;
121	        add_header Cache-Control "no-cache";
122	        return 200 'window.__DATAQ_CONFIG__={"auth":{"mode":"${DATAQ_AUTH_MODE}","authority":"${DATAQ_AUTH_AUTHORITY}","clientId":"${DATAQ_AUTH_CLIENT_ID}","apiScope":"${DATAQ_AUTH_API_SCOPE}","scope":"${DATAQ_AUTH_SCOPE}","logoutStyle":"${DATAQ_AUTH_LOGOUT_STYLE}"}};';
123	    }
124	
125	    # Runtime DNS resolver from the running container's /etc/resolv.conf. The nginx
126	    # image's own 15-local-resolvers.envsh (enabled via NGINX_ENTRYPOINT_LOCAL_RESOLVERS
127	    # in the Dockerfile) exports the resolv.conf nameservers into the variable
128	    # substituted below, before the startup envsubst, so this is cloud-neutral
129	    # (ADR 0028): compose's embedded DNS (127.0.0.11), ACA/K8s cluster DNS, etc. —
130	    # no resolver IP baked into the image (a literal 127.0.0.11 would break in ACA).
131	    # Resolving the upstream through a variable (below) defers DNS to request time,
132	    # so this image starts even while the api is still coming up and survives an api
133	    # restart (new IP) — a literal proxy_pass host is resolved once at startup and
134	    # would hard-crash nginx if the api isn't up yet.
135	    resolver ${NGINX_LOCAL_RESOLVERS} ipv6=off valid=10s;
136	
137	    # REST API — same-origin /api/* forwarded to the backend. proxy_pass uses a
138	    # variable, so the original URI isn't auto-appended; $request_uri carries the
139	    # full path + query (/api/v1/...) through unchanged.
140	    #
141	    # Host is intentionally NOT overridden to the browser's $host: when the
142	    # upstream is a real hostname behind a routing front-door (ACA's Envoy routes
143	    # external ingress by the app FQDN), the Host must match the upstream, or the
144	    # request is misrouted (404). nginx's default is Host = $proxy_host (the
145	    # upstream host), which is correct for BOTH compose (`api:8000`, uvicorn
146	    # ignores it) and ACA (the api FQDN). proxy_ssl_server_name sends the matching
147	    # TLS SNI for the https (ACA) upstream; it's a no-op for the http (compose) one.
148	    #
149	    # proxy_http_version 1.1 is REQUIRED: nginx proxies as HTTP/1.0 by default, and
150	    # Azure Container Apps' ingress rejects HTTP/1.0 with "426 Upgrade Required" —
151	    # so /api + /healthz must force 1.1 (like /mcp already does). Clearing the
152	    # Connection header keeps upstream keep-alive clean. (uvicorn in compose is fine
153	    # with either, so this is safe for the local path too.)
154	    location /api/ {
155	        set $dataq_upstream "${DATAQ_API_UPSTREAM}";
156	        proxy_pass $dataq_upstream$request_uri;
157	        proxy_http_version 1.1;
158	        proxy_set_header Connection "";
159	        proxy_ssl_server_name on;
160	        proxy_set_header X-Real-IP $remote_addr;
161	        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
162	        proxy_set_header X-Forwarded-Proto $dataq_forwarded_proto;
163	        # Verified above, stripped here (#1355 review): the origin secret must
164	        # not ride into the backend request context, where a traceback-locals
165	        # capture (#536 class) or a dependency's header logging (#849 class)
166	        # could surface it.
167	        proxy_set_header X-DataQ-Origin-Secret "";
168	    }
169	
170	    # Liveness probe — the api's top-level /healthz (NOT under /api), proxied here
171	    # so it stays externally reachable through the product host now that the api has
172	    # no public ingress (ADR 0028 §5). Exact-match so it can't shadow an SPA route;
173	    # without this, /healthz would fall through to the SPA index.html below. Same
174	    # Host/SNI + HTTP/1.1 handling as /api (ACA 426s HTTP/1.0).
175	    location = /healthz {
176	        set $dataq_upstream "${DATAQ_API_UPSTREAM}";
177	        proxy_pass $dataq_upstream$request_uri;
178	        proxy_http_version 1.1;
179	        proxy_set_header Connection "";
180	        proxy_ssl_server_name on;
181	        proxy_set_header X-Real-IP $remote_addr;
182	        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
183	        proxy_set_header X-Forwarded-Proto $dataq_forwarded_proto;
184	        # Verified above, stripped here (#1355 review): the origin secret must
185	        # not ride into the backend request context, where a traceback-locals
186	        # capture (#536 class) or a dependency's header logging (#849 class)
187	        # could surface it.
188	        proxy_set_header X-DataQ-Origin-Secret "";
189	    }
190	
191	    # MCP sub-app (FastMCP at /mcp). Streamable-HTTP/SSE needs HTTP/1.1 with no
192	    # response buffering and no hop-by-hop Connection header, or events stall.
193	    location /mcp {
194	        set $dataq_upstream "${DATAQ_API_UPSTREAM}";
195	        proxy_pass $dataq_upstream$request_uri;
196	        proxy_ssl_server_name on;
197	        proxy_http_version 1.1;
198	        proxy_set_header Connection "";
199	        proxy_buffering off;
200	        proxy_set_header X-Real-IP $remote_addr;
201	        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
202	        proxy_set_header X-Forwarded-Proto $dataq_forwarded_proto;
203	        # Verified above, stripped here (#1355 review): the origin secret must
204	        # not ride into the backend request context, where a traceback-locals
205	        # capture (#536 class) or a dependency's header logging (#849 class)
206	        # could surface it.
207	        proxy_set_header X-DataQ-Origin-Secret "";
208	    }
209	
210	    # Long-cache the fingerprinted build output; never cache index.html (it points
211	    # at the current asset hashes).
212	    #
213	    # **Matched on the FILE, not on the `/assets/` prefix** — and that is load-bearing.
214	    # Vite emits its bundle to `dist/assets/`, which collides head-on with the app's
215	    # own `/assets` SPA route (the ADR 0034 asset browse). A prefix `location /assets/`
216	    # swallows that whole path space: `/assets/<uuid>` matched here, hit `=404`, and
217	    # never reached the SPA fallback — so every asset deep link, bookmark and
218	    # browser-refresh 404'd in production while in-app navigation looked perfectly fine.
219	    # A regex location also takes precedence over the prefix `location /`, so the real
220	    # build files still get the immutable long-cache they need.
221	    location ~* ^/assets/.+\.(?:js|mjs|css|map|png|jpe?g|gif|svg|ico|webp|avif|woff2?|ttf|eot)$ {
222	        try_files $uri =404;
223	        expires 1y;
224	        add_header Cache-Control "public, immutable";
225	    }
226	
227	    # SPA fallback: any non-file path returns index.html so client-side routes
228	    # (deep links like /results/:runId, /assets/:assetId) resolve to the app.
229	    #
230	    # No `$uri/` in try_files — deliberately. With it, a request for `/assets` found
231	    # the on-disk `assets/` DIRECTORY and nginx issued its own 301 to `/assets/`,
232	    # rebuilt from the *internal* scheme/port — so the browser was handed
233	    # `http://…:8080/assets/` (plaintext, unroutable container port) and simply hung.
234	    # An SPA never wants directory-index redirects; every non-file path is a route.
235	    location / {
236	        try_files $uri /index.html;
237	        add_header Cache-Control "no-cache";
238	    }
239	}
