async () => {
  const authority = window.__DATAQ_CONFIG__.auth.authority;
  const out = {};
  // 1. The exact discovery fetch oidc-client-ts performs at sign-in.
  try {
    const r = await fetch(`${authority}/.well-known/openid-configuration`);
    const j = await r.json();
    out.discovery = `OK ${r.status}`;
    out.tokenEndpoint = j.token_endpoint;
    // 2. The JWKS fetch, and 3. a preflight against the TOKEN endpoint host —
    //    the one that sits OUTSIDE the authority's path prefix, i.e. the case
    //    that would break if connect-src were derived from the authority.
    const jr = await fetch(j.jwks_uri);
    out.jwks = `OK ${jr.status}`;
    const tr = await fetch(j.token_endpoint, { method: 'POST', body: 'grant_type=invalid' });
    out.tokenEndpointReachable = `reached, HTTP ${tr.status} (400 = server rejected the dummy grant, NOT a CSP block)`;
  } catch (e) { out.error = String(e); }
  // Negative control: the policy must still be live.
  try { await fetch('https://cdn.jsdelivr.net/npm/left-pad@1.3.0/index.js'); out.control = 'ALLOWED — csp not enforcing!'; }
  catch (e) { out.control = 'blocked (csp enforcing)'; }
  return out;
}

